if %count%==5 (
    echo [SUCCESS] ALLE TASKS KORREKT EINGERICHTET!
    echo.
    echo Najika Training startet automatisch:
    echo   - Jeden Montag-Freitag
    echo   - Um 09:00, 10:00, 11:00, 12:00, 13:00 Uhr
